@push('scripts')<script>
$(function(){
 const modal=new bootstrap.Modal('#equipmentModal'), productModal=new bootstrap.Modal('#equipmentProductModal'), supplierModal=new bootstrap.Modal('#equipmentSupplierModal'), detailModal=new bootstrap.Modal('#equipmentDetailModal'); let activeLine=null;
 const table=$('#equipmentTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.equipment-receipts.dt')),data:d=>{d.from_date=$('#equipmentFrom').val();d.to_date=$('#equipmentTo').val()}},columns:[{data:'id',orderable:false,searchable:false,render:(d,t,r,m)=>m.row+m.settings._iDisplayStart+1},{data:'actions',orderable:false,searchable:false,className:'text-center'},{data:'ownership_label',name:'ownership_type'},{data:'number',name:'number'},{data:'date_label',name:'receipt_date'},{data:'invoice_number',name:'invoice_number',defaultContent:'—'},{data:'invoice_date_label',name:'invoice_date'},{data:'supplier_name',orderable:false,searchable:false},{data:'description',name:'description',defaultContent:'—'}],order:[[4,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 const products=$('#equipmentProducts').DataTable({processing:true,serverSide:true,ajax:@json(route('super.equipment-receipts.products.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'category_label',orderable:false,searchable:false},{data:'unit_label',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}]});
 const suppliers=$('#equipmentSuppliers').DataTable({processing:true,serverSide:true,ajax:@json(route('super.equipment-receipts.suppliers.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'actions',orderable:false,searchable:false}]});
 function reset(){ $('#equipmentForm')[0].reset();$('#equipmentId,#equipmentSupplierId').val('');$('#equipmentSupplierLabel').val('');$('#equipmentLines').empty();$('#equipmentDate').val(@json(now()->toDateString()));$('#equipmentModalTitle').text(@json(__('ui.machine_receipt.add')));$('#equipmentNumber').val(@json(__('ui.scrap_receipt.number_loading')));$.get(@json(route('super.equipment-receipts.number-preview'))).done(r=>$('#equipmentNumber').val(r.number)); addLine(); }
 function addLine(v={}){const ix=$('#equipmentLines tr').length, row=$(`<tr><td><div class="input-group input-group-sm"><input class="form-control line-code" readonly><button class="btn btn-outline-primary choose-product" type="button">...</button><input type="hidden" class="line-product" name="items[${ix}][product_id]"></div></td><td><input class="form-control form-control-sm line-name" readonly></td><td><input class="form-control form-control-sm line-unit" readonly></td><td><input type="number" min="0.0001" step="0.0001" required name="items[${ix}][quantity]" class="form-control form-control-sm line-qty"></td><td><input type="number" min="0" step="0.0001" name="items[${ix}][unit_price]" class="form-control form-control-sm line-price"></td><td><input class="form-control form-control-sm line-total" readonly></td><td><input name="items[${ix}][supplier_po_number]" class="form-control form-control-sm"></td><td><input name="items[${ix}][description]" class="form-control form-control-sm"></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-line"><i data-feather="trash-2" class="icon-sm"></i></button></td></tr>`); row.find('.line-code').val(v.item_code||'');row.find('.line-name').val(v.item_name||'');row.find('.line-unit').val(v.unit||'');row.find('.line-product').val(v.product_id||'');row.find('.line-qty').val(v.quantity||'');row.find('.line-price').val(v.unit_price||''); row.find('.line-total').val(v.total_price||''); row.find('.line-qty,.line-price').on('input',()=>row.find('.line-total').val((Number(row.find('.line-qty').val())*Number(row.find('.line-price').val())).toFixed(4)));$('#equipmentLines').append(row); }
 $('#addEquipmentLine').on('click',()=>addLine());$('#equipmentLines').on('click','.remove-line',function(){if($('#equipmentLines tr').length>1)$(this).closest('tr').remove()});$('#equipmentLines').on('click','.choose-product',function(){activeLine=$(this).closest('tr');productModal.show()});
 $('#chooseEquipmentSupplier').on('click',()=>supplierModal.show());$(document).on('click','.btn-select-equipment-product',function(){const b=$(this);activeLine.find('.line-code').val(b.data('code'));activeLine.find('.line-name').val(b.data('name'));activeLine.find('.line-unit').val(b.data('unit'));activeLine.find('.line-product').val(b.data('id'));activeLine.find('.line-price').val(b.data('price')||0).trigger('input');productModal.hide()});$(document).on('click','.btn-select-equipment-supplier',function(){const b=$(this);$('#equipmentSupplierId').val(b.data('id'));$('#equipmentSupplierLabel').val(b.data('name'));supplierModal.hide()});
 $('#addEquipmentReceipt').on('click',()=>{reset();modal.show()});$('#showEquipment').on('click',()=>table.ajax.reload());$('#equipmentFrom,#equipmentTo').on('change',()=>table.ajax.reload());$('#exportEquipment').on('click',function(e){e.preventDefault();location.href=this.href+'?'+$.param({from_date:$('#equipmentFrom').val(),to_date:$('#equipmentTo').val()})});
 $(document).on('click','.btn-edit-equipment,.btn-detail-equipment',function(){const id=$(this).data('id'),detail=$(this).hasClass('btn-detail-equipment');$.get(@json(route('super.equipment-receipts.show',['equipmentReceipt'=>'__ID__'])).replace('__ID__',id)).done(d=>{if(detail){$('#equipmentDetailTitle').text(d.number);$('#equipmentDetailHeader').html(`<div class="col-md-3"><b>{{ __('ui.machine_receipt.date') }}</b><br>${d.receipt_date}</div><div class="col-md-3"><b>{{ __('ui.machine_receipt.ownership') }}</b><br>${$('<div>').text(d.ownership_label).html()}</div><div class="col-md-3"><b>{{ __('ui.machine_receipt.supplier') }}</b><br>${$('<div>').text(d.supplier?.name||'—').html()}</div><div class="col-md-3"><b>{{ __('ui.machine_receipt.invoice_number') }}</b><br>${$('<div>').text(d.invoice_number||'—').html()}</div>`);$('#equipmentDetailLines').html(d.items.map(i=>`<tr><td>${$('<div>').text(i.item_code).html()}</td><td>${$('<div>').text(i.item_name).html()}</td><td>${$('<div>').text(i.unit).html()}</td><td>${i.quantity}</td><td>${i.unit_price}</td><td>${i.total_price}</td><td>${$('<div>').text(i.supplier_po_number||'—').html()}</td><td>${$('<div>').text(i.description||'—').html()}</td></tr>`).join(''));detailModal.show();return}reset();$('#equipmentId').val(d.id);$('#equipmentNumber').val(d.number);$('#equipmentDate').val(d.receipt_date);$('#equipmentOwnership').val(d.ownership_type);$('#equipmentSupplierId').val(d.supplier_id||'');$('#equipmentSupplierLabel').val(d.supplier?.name||'');$('#equipmentInvoice').val(d.invoice_number||'');$('#equipmentInvoiceDate').val(d.invoice_date||'');$('#equipmentCurrency').val(d.currency_code||'');$('#equipmentDescription').val(d.description||'');$('#equipmentLines').empty();d.items.forEach(i=>addLine({...i}));$('#equipmentModalTitle').text(@json(__('ui.common.edit'))+' {{ __('ui.machine_receipt.title') }}');modal.show()})});
 $(document).on('click','.btn-delete-equipment',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:@json(route('super.equipment-receipts.destroy',['equipmentReceipt'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||@json(__('ui.workflow.save_failed'))}))})});
 $('#equipmentForm').on('submit',function(e){e.preventDefault();const id=$('#equipmentId').val(),url=id?@json(route('super.equipment-receipts.update',['equipmentReceipt'=>'__ID__'])).replace('__ID__',id):@json(route('super.equipment-receipts.store'));$.ajax({url,method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);Swal.fire({icon:'success',text:`${r.message} (${r.number})`})}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||@json(__('ui.workflow.save_failed'))}))});
});
</script>@endpush
